import{_ as a,H as e,f as i,i as t}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"09 | 开源的PlaywrightMCPServer：意图驱动测试自动化革命","description":"","frontmatter":{},"headers":[{"level":2,"title":"给你的自动化安装“涡轮引擎”","slug":"给你的自动化安装-涡轮引擎","link":"#给你的自动化安装-涡轮引擎","children":[]},{"level":2,"title":"实际动动手——让大模型完成自动化测试","slug":"实际动动手——让大模型完成自动化测试","link":"#实际动动手——让大模型完成自动化测试","children":[]},{"level":2,"title":"Playwright MCP 的一些技巧","slug":"playwright-mcp-的一些技巧","link":"#playwright-mcp-的一些技巧","children":[{"level":3,"title":"测试提示词要简单清晰","slug":"测试提示词要简单清晰","link":"#测试提示词要简单清晰","children":[]},{"level":3,"title":"用.txt 保存测试逻辑描述的提示词","slug":"用-txt-保存测试逻辑描述的提示词","link":"#用-txt-保存测试逻辑描述的提示词","children":[]},{"level":3,"title":"启动配置的使用","slug":"启动配置的使用","link":"#启动配置的使用","children":[]}]},{"level":2,"title":"结语","slug":"结语","link":"#结语","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]},{"level":2,"title":"附录：Playwright MCP Server 的启动配置","slug":"附录-playwright-mcp-server-的启动配置","link":"#附录-playwright-mcp-server-的启动配置","children":[]}],"relativePath":"AI重塑测试开发系统实践/09｜开源的PlaywrightMCPServer：意图驱动测试自动化革命.md","filePath":"AI重塑测试开发系统实践/09｜开源的PlaywrightMCPServer：意图驱动测试自动化革命.md","lastUpdated":1795562968000}'),l={name:"AI重塑测试开发系统实践/09｜开源的PlaywrightMCPServer：意图驱动测试自动化革命.md"};function n(p,s,r,h,o,E){return e(),i("div",null,[...s[0]||(s[0]=[t(`<h1 id="_09-开源的playwrightmcpserver-意图驱动测试自动化革命" tabindex="-1">09 | 开源的PlaywrightMCPServer：意图驱动测试自动化革命 <a class="header-anchor" href="#_09-开源的playwrightmcpserver-意图驱动测试自动化革命" aria-label="Permalink to &quot;09 | 开源的PlaywrightMCPServer：意图驱动测试自动化革命&quot;">​</a></h1><p>你好，我是陈磊。</p><p>上节课我们详细介绍了 MCP Server，并探讨了 MCP 协议的本质，在当下 DevOps 浪潮中，MCP 和大模型对测试的赋能潜力无限，测试将从“被动检查”转向“主动预防”，大模型预判潜在缺陷，提前生成防护脚本。MCP 不只省时省力，更是在重塑测试开发工程师的职业边界——测试开发工程师从脚本的奴隶解放为质量架构师，专注于业务逻辑而非技术细节。</p><p>传统自动化测试像写论文一样，盯着 Selenium 或 Playwright 文档，敲出一堆 XPath 定位、等待条件、断言逻辑。稍有疏忽，浏览器一刷新就报错，新人上手得哭着学一周。</p><p>而 MCP 让一切流程像买东西一样直白：你对大模型说，“测测极客时间首页：搜索‘接口测试入门课’，点击”单课购买“按钮，结算页面检查总价是否 68 元，哦，对了，用 Chrome 模拟手机端。” AI 瞬间“懂你”，通过 MCP 协议调用浏览器工具，直接执行需要验证的流程，是不是很神奇。今天我就使用微软开源的 Playwright MCP Server，带你一起感受一下 MCP 对于自动化测试的”涡轮引擎“提速。</p><h2 id="给你的自动化安装-涡轮引擎" tabindex="-1">给你的自动化安装“涡轮引擎” <a class="header-anchor" href="#给你的自动化安装-涡轮引擎" aria-label="Permalink to &quot;给你的自动化安装“涡轮引擎”&quot;">​</a></h2><p>好，理论部分我们已经聊够了，现在是时候动真格的了！别担心，整个安装和基本使用过程超级简单，我会一步步带你走，保证你 10 分钟内就能让它跑起来。想象一下：通过自然语言描述一个浏览器操作流程，大模型就能自动驱动浏览器执行测试、验证结果，甚至截图确认。这不仅仅是工具，更是未来 UI 自动化测试的革命性玩法。在开始之前，需要先确保你的电脑满足以下条件：</p><ul><li><p>Node.js 版本：18 或以上。你可以去 Node.js 官网下载安装。如果不确定版本，打开终端运行 node -v 检查。</p></li><li><p>Playwright 安装：这是关键依赖。Playwright 是微软开发的一个强大 Web 自动化测试框架，支持 Chromium、Firefox 和 WebKit 浏览器，能模拟真实用户行为，如点击、输入、截图等。</p></li></ul><p>看到这里你可能有点懵：我们不是要安装 Playwright MCP Server 吗？为什么还要先装Playwright？简单解释一下：Playwright MCP Server 是一个基于 Playwright 的工具服务器，它提供浏览器自动化功能，比如导航页面、点击元素、执行脚本等。但它依赖 Playwright 作为底层引擎——没有 Playwright，服务器就无法启动浏览器。</p><p>换句话说，Playwright 是“发动机”，MCP Server 是“方向盘”。这个网络上很多，我们这里就跳过安装 plauwright 的教程了。现在，我们来安装核心组件：Playwright MCP Server。我推荐使用 mcp-get 工具，它是 Anthropic 提供的 MCP 服务器管理器，超级方便。在终端运行以下命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>npx @michaellatman/mcp-get@latest install @executeautomation/playwright-mcp-serve</span></span></code></pre></div><p>这个命令会下载并配置服务器。如果你是 Claude Desktop 用户（Anthropic 的桌面版 AI 工具），安装中可能会看到 Claude Desktop 自动重启一次。这是正常现象——它在后台集成MCP Server，确保与 Claude 无缝对接。重启后，服务器就配置好了，你可以直接在 Claude中使用。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E9%87%8D%E5%A1%91%E6%B5%8B%E8%AF%95%E5%BC%80%E5%8F%91%E7%B3%BB%E7%BB%9F%E5%AE%9E%E8%B7%B5/images/09/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E9%87%8D%E5%A1%91%E6%B5%8B%E8%AF%95%E5%BC%80%E5%8F%91%E7%B3%BB%E7%BB%9F%E5%AE%9E%E8%B7%B5/images/09/1.png" alt=""></a></p><p>如果你使用的不是 Cluade Desktop 也不用担心，你可以用其他 MCP Host（如 VS Code 扩展或自定义脚本）。只需将以下 JSON 配置复制到你的 MCP Host 的配置文件（通常是 mcp.json或类似文件）中，保存后，重启你的 MCP Host，服务器就启动了。配置路径因工具而异，建议查阅你的 Host 文档。</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> &quot;mcpServers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">   &quot;playwright&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">     &quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;npx&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">     &quot;args&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">       &quot;@playwright/mcp@latest&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">     ]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">   }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>配置完成后，在 Claude Desktop（或其他 Host）中，点击 MCP Server 记录，你就能看到它提供的工具列表。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E9%87%8D%E5%A1%91%E6%B5%8B%E8%AF%95%E5%BC%80%E5%8F%91%E7%B3%BB%E7%BB%9F%E5%AE%9E%E8%B7%B5/images/09/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E9%87%8D%E5%A1%91%E6%B5%8B%E8%AF%95%E5%BC%80%E5%8F%91%E7%B3%BB%E7%BB%9F%E5%AE%9E%E8%B7%B5/images/09/2.png" alt=""></a></p><p>如上图所示，工具大致分为几类（基于 Playwright 的能力）：</p><ul><li><p>页面导航与交互：如 navigate（导航到 URL）、click（点击元素）、fill（填充表单）、presskey（按键输入）。</p></li><li><p>内容获取与验证：如 get visible text（获取可见文本）、get visible html（获取可见HTML）、assert response（断言响应）。</p></li><li><p>高级操作：如 upload file（上传文件）、drag（拖拽）、screenshot（截图）、save as pdf（保存为 PDF）。</p></li><li><p>会话管理：如 start codegen session（启动代码生成会话，用于记录用户操作生成脚本）。</p></li></ul><p>这些工具让浏览器自动化变得模块化，大模型分析你的需求后，会自动挑选合适的工具组合执行。</p><h2 id="实际动动手——让大模型完成自动化测试" tabindex="-1">实际动动手——让大模型完成自动化测试 <a class="header-anchor" href="#实际动动手——让大模型完成自动化测试" aria-label="Permalink to &quot;实际动动手——让大模型完成自动化测试&quot;">​</a></h2><p>配置好了？来实战一下！我们用一个简单场景测试：模拟用户在极客时间首页的操作。这相当于一个 UI 自动化测试用例，通过自然语言描述，就能让 Claude + Playwright MCP Server自动执行。测试输入的提示词如下所示：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>访问https://time.geekbang.org/,如果有弹窗,点击关闭按钮,在做后面操作。在搜索框中搜索”接口测试</span></span></code></pre></div><p>它会先解析你的需求，发现涉及 Web 操作（如导航、搜索、点击、验证）。然后，扫描可用工具，看到 “Playwright navigate”“Playwright click”“Playwright fill” 等完美匹配。这时，Claude会请求你的许可——因为这些是第三方集成，涉及浏览器隐私和安全。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E9%87%8D%E5%A1%91%E6%B5%8B%E8%AF%95%E5%BC%80%E5%8F%91%E7%B3%BB%E7%BB%9F%E5%AE%9E%E8%B7%B5/images/09/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E9%87%8D%E5%A1%91%E6%B5%8B%E8%AF%95%E5%BC%80%E5%8F%91%E7%B3%BB%E7%BB%9F%E5%AE%9E%E8%B7%B5/images/09/3.png" alt=""></a></p><p>许可通过后，Claude 调用 navigate 工具，导航到首页。响应了：Navigated tohttps://time.geekbang.org/，响应确认导航成功，突出 URL 和 headless 模式。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E9%87%8D%E5%A1%91%E6%B5%8B%E8%AF%95%E5%BC%80%E5%8F%91%E7%B3%BB%E7%BB%9F%E5%AE%9E%E8%B7%B5/images/09/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E9%87%8D%E5%A1%91%E6%B5%8B%E8%AF%95%E5%BC%80%E5%8F%91%E7%B3%BB%E7%BB%9F%E5%AE%9E%E8%B7%B5/images/09/4.png" alt=""></a></p><p>在完成这部分后，Claude 继续调用 screenshot 工具，捕获当前页面状态（例如首页加载后）。截图保存到本地目录，并存入内存以供后续验证。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E9%87%8D%E5%A1%91%E6%B5%8B%E8%AF%95%E5%BC%80%E5%8F%91%E7%B3%BB%E7%BB%9F%E5%AE%9E%E8%B7%B5/images/09/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E9%87%8D%E5%A1%91%E6%B5%8B%E8%AF%95%E5%BC%80%E5%8F%91%E7%B3%BB%E7%BB%9F%E5%AE%9E%E8%B7%B5/images/09/5.png" alt=""></a></p><p>Claude 会像流水线一样：关闭弹窗 → 调用 fill 工具完成填充搜索框→ 调用 click 工具完成点击搜索→ 利用 get visible text 工具配合断言验证结果→ 点击课程 → 验证详情页 → 点击购买按钮 → 确认登录跳转。每个步骤都会调用正确的工具，操作后，可能再截图或日志验证，确保无误。整个过程完成后，Claude 会总结结果，比如“测试通过：成功跳转到登录页，无异常”。</p><h2 id="playwright-mcp-的一些技巧" tabindex="-1">Playwright MCP 的一些技巧 <a class="header-anchor" href="#playwright-mcp-的一些技巧" aria-label="Permalink to &quot;Playwright MCP 的一些技巧&quot;">​</a></h2><h3 id="测试提示词要简单清晰" tabindex="-1">测试提示词要简单清晰 <a class="header-anchor" href="#测试提示词要简单清晰" aria-label="Permalink to &quot;测试提示词要简单清晰&quot;">​</a></h3><p>在 Playwright MCP Server 的使用中，提示工程（Prompt Engineering）是核心技能。它决定了大模型能否准确理解你的意图，并生成高效、可维护的 Playwright 代码。模糊的提示往往导致大模型产出不完整、冗余或错误的脚本，而结构化的、详细的提示则能让大模型像专业测试开发工程师一样，输出干净的测试流程。</p><p>如果我在测试用例的提示词中和大模型性”访问这个网址“，这样可能会让大模型忽略浏览器上下文、错误处理或验证步骤。我可能得到了一个 playwright navigate 工具的效用，但是工具输入的 request 却如下面所示。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{</span></span>
<span class="line"><span> \`url\`: \`https://example.com\`,</span></span>
<span class="line"><span> \`headless\`: false</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>也有可能通过上下文得到了一个正确的 request 请求，但是忽略了加载等待、弹窗处理或网络失败重试等等，从而增加了很多的调试时间。详细步骤能引导大模型构建完整的测试链条：动作、验证、异常处理。写测试流程提示词的一些核心的原则如下：</p><ul><li><p>具体性：清晰的 URL，明确的动作，清晰的输入以及正确的结果验证。</p></li><li><p>顺序性：按顺序描述，尽量避免多分支情况在一个测试逻辑描述的提示词里，多个业务逻辑分支可以放到多个测试逻辑描述的提示词里。</p></li><li><p>验证与错误处理：总是包含“检查 / 验证”步骤，这样可以让大模型每一步都自己对自己的结果做一次检验。</p></li><li><p>简洁：测试逻辑描述的提示词要简洁明了，尽量去除无关的词汇，例如“请你帮我打开极客时间的首页”就不如“访问 <a href="https://time.geekbang.org/%E2%80%9D%EF%BC%8C%E6%9B%B4%E5%8A%A0%E5%AE%B9%E6%98%93%E8%AE%A9%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%90%86%E8%A7%A3%E3%80%82" target="_blank" rel="noreferrer">https://time.geekbang.org/”，更加容易让大模型理解。</a></p></li></ul><h3 id="用-txt-保存测试逻辑描述的提示词" tabindex="-1">用.txt 保存测试逻辑描述的提示词 <a class="header-anchor" href="#用-txt-保存测试逻辑描述的提示词" aria-label="Permalink to &quot;用.txt 保存测试逻辑描述的提示词&quot;">​</a></h3><p>.txt 文件简单、轻量，便于 Git 版本控制和团队协作。它像一个“测试用例库”，每个文件对应一个场景，避免散乱的笔记。结构化格式让大模型容易解析。推荐团队内部定义统一的描述方式，每个测试场景都保存在一个独立的.txt 文件中，每个场景文件命名都是按照某一种命名规则，这样做到见文知意，从文件名就可以了解对应的文件所要检查的动作和结果，下面是一个例子。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>场景：电商ABC网站搜索功能测试，确保结果相关性。</span></span></code></pre></div><ul><li>前提：浏览器已启动，无需登录。步骤：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 打开首页 https://www.example-ecommerce.com。</span></span>
<span class="line"><span>2. 在搜索框（class=&#39;search-input&#39;）输入 &#39;无线耳机&#39;。</span></span>
<span class="line"><span>3. 点击搜索按钮（aria-label=&#39;Search&#39;）或按 Enter。</span></span></code></pre></div><ul><li>预期：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1、页面 URL 变化为 /search?q=无线耳机。</span></span>
<span class="line"><span>2、结果列表中至少 5 个产品，标题包含 &#39;耳机&#39;。</span></span>
<span class="line"><span>3、如果无结果，显示&#39;No matches&#39; 消息并截图。</span></span></code></pre></div><p>你可以找到更适合你们内部的办法，去定义一种描述方式，我们要保证尽最大努力的简单、明了，同时描述的时候要尽量让每一个 token 都有明确的语义价值。</p><h3 id="启动配置的使用" tabindex="-1">启动配置的使用 <a class="header-anchor" href="#启动配置的使用" aria-label="Permalink to &quot;启动配置的使用&quot;">​</a></h3><p>Playwright MCP Server 不是 Claude 专属，它支持多种大模型，通过标准化 MCP 协议实现跨模型兼容。因此你可以利用任何一个 MCP Host，在任何一个支持 MCP 协议的大模型的助力下，完成自动化测试。更多详细的 Playwright MCP Server 的内容你可以进度 PlaywrightMCP Server 的官方Github 仓库查看。</p><p>Claude Desktop 对于 MCP Server 的配置相对比较自动化，如果你使用了另外一种 MCPHost，那么就需要手动进入 MCP Server 的配置文件中进行配置，我前面已经给出了配置文件的样子。</p><p>在 Playwright MCP Server 的官方 Github 仓库的说明文档里面，还介绍了 Playwright MCPServer 的一些启动配置，很多选项在测试过程中也是常用到的，例如”–headless“表示启动无头浏览器，”–save-trace“是将 Playwright 的 trace 信息到保存到一个目录，常和“–output-dir”一起使用，所有的这些选项都是继承自 Playwright API，对应的说明我放到这节课的最后了，你可以保存起来需要的时候再看一看。</p><p>这些配置在 MCP Server 的配置文件就按照如下的格式，放到 args 节点下面就可以了。</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> &quot;mcpServers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">   &quot;playwright&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">     &quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;npx&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">     &quot;args&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">       &quot;@playwright/mcp@latest&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">       &quot;--headless&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">       &quot;--browser=firefox&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">     ]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">   }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to &quot;结语&quot;">​</a></h2><p>今天我们就聊到这里了，怎么样，Playwright MCP Server 是不是让你眼前一亮？它不只是工具，更是你的 UI 自动化测试的“超级英雄披风”。我今天和你一起开启了一段神器的测试工作，通过自然语言完成了自动化测试，我们通过描述测试意图，大模型负责利用 PlaywrightMCP Server 完成测试，这一个看似简单的过程是从“脚本驱动”到“AI 意图驱动”的范式革命，测试工程师从“码奴”变“策略师”，专注设计场景而非纠缠细节。你一定要抽时间动手试一试，当你自己动手去感受过，才能体会到里面的美妙之处。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>无论你用 Playwright MCP Server 和大模型做了什么样的事情，我都很期待在评论区看到你的“测试意图”。如果你没什么合适的实验想法，那么可以试试这套流程“从极客时间首页，到为你推荐课程的第一门课程的详情，查看课程目录，并选择一节试读课进行试看”，欢迎你在评论区留下你的测试意图描述，也欢迎你把这节课分享给其他朋友，我们下节课再见！</p><h2 id="附录-playwright-mcp-server-的启动配置" tabindex="-1">附录：Playwright MCP Server 的启动配置 <a class="header-anchor" href="#附录-playwright-mcp-server-的启动配置" aria-label="Permalink to &quot;附录：Playwright MCP Server 的启动配置&quot;">​</a></h2><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E9%87%8D%E5%A1%91%E6%B5%8B%E8%AF%95%E5%BC%80%E5%8F%91%E7%B3%BB%E7%BB%9F%E5%AE%9E%E8%B7%B5/images/09/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E9%87%8D%E5%A1%91%E6%B5%8B%E8%AF%95%E5%BC%80%E5%8F%91%E7%B3%BB%E7%BB%9F%E5%AE%9E%E8%B7%B5/images/09/6.png" alt=""></a></p>`,57)])])}const d=a(l,[["render",n]]);export{c as __pageData,d as default};
